<?php
namespace App\Jobs;
use App\Domain\Imports\{ImportStatus,SchemaInferer,SourceReaderFactory};use App\Models\DataImport;use App\Services\OperationalMetrics;use Illuminate\Bus\Queueable;use Illuminate\Contracts\Queue\ShouldQueue;use Illuminate\Foundation\Bus\Dispatchable;use Illuminate\Queue\{InteractsWithQueue,SerializesModels};use Illuminate\Support\Facades\Storage;use RuntimeException;
final class AnalyzeImport implements ShouldQueue{use Dispatchable,InteractsWithQueue,Queueable,SerializesModels;public int $tries=3;public array $backoff=[5,30,120];public function __construct(public string $importId){}
 public function handle(SourceReaderFactory $factory,SchemaInferer $inferer,OperationalMetrics $metrics):void{$import=DataImport::findOrFail($this->importId);$import->update(['status'=>ImportStatus::Analyzing]);try{$stream=Storage::disk(config('filesystems.default'))->readStream($import->storage_key);if(!is_resource($stream))throw new RuntimeException('Unable to read import object');}catch(\Throwable $e){$metrics->storageFailure($import->organization_id);throw $e;}try{$analysis=$factory->make($import->source_type)->analyze($stream,$import->source_options_json??[]);}finally{fclose($stream);}$import->update(['status'=>ImportStatus::Ready,'detected_row_count'=>$analysis['count'],'source_options_json'=>array_merge($import->source_options_json??[],$analysis['options']??[]),'source_schema_json'=>['format'=>$analysis['format'],'headers'=>$analysis['headers'],'inferred'=>$inferer->infer($analysis['sample']),'sample'=>$analysis['sample'],'sheets'=>$analysis['sheets']??null]]);}
 public function failed(?\Throwable $e):void{DataImport::whereKey($this->importId)->update(['status'=>ImportStatus::Failed]);}}
